// Install a finished build into the repository: verify, copy, and regenerate the committed identity module.
//
//   node vendor/highs/build/install-artifacts.mjs <out-dir>
//
// <out-dir> is the build's `out/` directory (highs.js, highs.wasm, highs-build-manifest.json), copied back from the build
// host. The script re-hashes the artifacts against the manifest, writes them to frontend/public (what the browser loads) and
// frontend/vendor/highs (the vendored provenance copy), re-hashes both copies, and rewrites
// src/solver/native/manifestData.ts, the identity the loader checks every loaded artifact against.
import { createHash } from 'node:crypto';
import { copyFileSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const frontend = resolve(here, '..', '..', '..');
const outDir = process.argv[2];
if (!outDir) {
  console.error('usage: node install-artifacts.mjs <out-dir>');
  process.exit(2);
}

const sha256 = (path) => createHash('sha256').update(readFileSync(path)).digest('hex');
const manifestPath = join(outDir, 'highs-build-manifest.json');
const manifest = JSON.parse(readFileSync(manifestPath, 'utf8'));
const names = ['highs.js', 'highs.wasm'];

for (const name of names) {
  const actual = sha256(join(outDir, name));
  const expected = manifest.artifacts[name].sha256;
  if (actual !== expected) throw new Error(`${name}: SHA-256 ${actual} does not match the manifest (${expected})`);
}

for (const dir of [join(frontend, 'public'), join(frontend, 'vendor', 'highs')]) {
  mkdirSync(dir, { recursive: true });
  for (const name of [...names, 'highs-build-manifest.json']) {
    copyFileSync(join(outDir, name), join(dir, name));
  }
  for (const name of names) {
    const actual = sha256(join(dir, name));
    if (actual !== manifest.artifacts[name].sha256) throw new Error(`${join(dir, name)}: copy differs from the build output`);
  }
  if (sha256(join(dir, 'highs-build-manifest.json')) !== sha256(manifestPath)) throw new Error(`${dir}: manifest copy differs`);
  console.log(`installed and verified ${dir}`);
}

const identity = {
  schema: manifest.schema,
  highs: {
    tag: manifest.inputs.highs.tag,
    commit: manifest.inputs.highs.commit,
    version: manifest.inputs.highs.version,
    githash: manifest.runtime.githash,
  },
  emscripten: { version: manifest.inputs.emscripten.version, emsdkCommit: manifest.inputs.emsdk.commit },
  sizeofHighsInt: manifest.runtime.sizeofHighsInt,
  exportedFunctions: manifest.build.exportedFunctions,
  exportedRuntimeMethods: manifest.build.exportedRuntimeMethods,
  artifacts: {
    'highs.js': manifest.artifacts['highs.js'],
    'highs.wasm': manifest.artifacts['highs.wasm'],
  },
};

const source = `/**
 * GENERATED by vendor/highs/build/install-artifacts.mjs from vendor/highs/highs-build-manifest.json. Do not edit.
 *
 * The identity of the committed native HiGHS build: what \`loadHighs\` verifies a loaded artifact against (SHA-256 of both
 * files, the version string, the githash, the HighsInt width and the exported function list). A test checks this module
 * against the committed manifest files.
 */

import type { HighsBuildIdentity } from './manifestTypes';

export const COMMITTED_HIGHS_BUILD: HighsBuildIdentity = ${JSON.stringify(identity, null, 2)};
`;
writeFileSync(join(frontend, 'src', 'solver', 'native', 'manifestData.ts'), source);
console.log('wrote src/solver/native/manifestData.ts');
